/* MyTennisCloud: one Elementor layout, responsive at every breakpoint. */
.mtc-section,.mtc-section *{box-sizing:border-box}
.mtc-section{--mtc-accent:#ed5700;min-width:0;max-width:100%}
.mtc-section .e-con,.mtc-section .elementor-widget{min-width:0}
.mtc-section img,.mtc-section video,.mtc-section iframe{max-width:100%}
.mtc-section img{height:auto}
.mtc-section .elementor-heading-title{overflow-wrap:break-word;text-wrap:balance}
.mtc-section p{overflow-wrap:break-word}
.mtc-section a:focus-visible,.mtc-section button:focus-visible,.mtc-section [tabindex]:focus-visible{outline:3px solid #ed5700;outline-offset:5px}
.mtc-section .elementor-button,.mtc-section .elementor-menu-toggle{min-height:44px;align-items:center;justify-content:center}
.mtc-section .elementor-button{white-space:normal;transition:transform .2s ease,box-shadow .2s ease,background-color .2s ease}
.mtc-section .mtc-service-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.mtc-section .mtc-service-grid>.e-con{width:100%;--width:100%;transition:transform .25s ease,box-shadow .25s ease}
.mtc-section .mtc-neuro-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.mtc-section .mtc-neuro-grid>.e-con{width:100%;--width:100%}
.mtc-section .orange-underline{animation-iteration-count:1;animation-fill-mode:forwards}
.mtc-section .team-track:hover,.mtc-section .team-track:focus-within{animation-play-state:paused}
.mtc-section .team-marquee{max-width:100%}
.mtc-section .custom-coach-card{max-width:100%;width:100%}
@media(hover:hover) and (prefers-reduced-motion:no-preference){
.mtc-section .elementor-button:hover{transform:translateY(-2px);box-shadow:0 8px 22px #0002}
.mtc-section .mtc-service-grid>.e-con:hover{transform:translateY(-4px);box-shadow:0 14px 32px #0001}
}
@media(min-width:1025px){.mtc-hero-title .elementor-heading-title{font-size:clamp(40px,4.45vw,64px);line-height:1.12}}
@media(max-width:1200px) and (min-width:1025px){.mtc-header .elementor-nav-menu a{padding-inline:9px!important;font-size:14px!important}.mtc-header{gap:12px!important}.mtc-hero-copy{width:75%!important;--width:75%}.mtc-hero-note{width:25%!important;--width:25%}}
@media(max-width:1024px){
